import numpy as np

def metrics(rows,start=0):
 r=rows[start:];base=r[0]['preperiod_equity'];curve=np.r_[base,[x['equity'] for x in r]];logs=np.log(curve[1:]/curve[:-1]);ex=np.array([sum(x['actual_weights'][:7]) for x in r]);turn=sum(x['turnover'] for x in r);months={}
 for x,v,e in zip(r,logs,ex):
  key=x['valuation_date'][:7];months.setdefault(key,{'log':0.,'ex':[]});months[key]['log']+=v;months[key]['ex'].append(e)
 monthly=[{'month':k,'return':float(np.expm1(v['log'])),'mean_exposure':float(np.mean(v['ex'])),'sessions':len(v['ex'])} for k,v in months.items()];mp=float(np.mean([x['return']>0 for x in monthly]));rolling=np.convolve(logs,np.ones(20),mode='valid') if len(logs)>=20 else np.array([]);rex=np.convolve(ex,np.ones(20)/20,mode='valid') if len(ex)>=20 else np.array([]);rp=float(np.mean(rolling>0)) if len(rolling) else None;dd=float(np.min(curve/np.maximum.accumulate(curve)-1));active_months=[x for x in monthly if x['mean_exposure']>=.25]
 return {'total_return':float(curve[-1]/base-1),'max_drawdown':dd,'mean_gross_exposure':float(ex.mean()),'median_gross_exposure':float(np.median(ex)),'invested_day_fraction_10pct':float(np.mean(ex>=.1)),'invested_day_fraction_25pct':float(np.mean(ex>=.25)),'max_stock_weight':max(max(x['actual_weights'][:7]) for x in r),'positive_month_fraction':mp,'monthly_returns':monthly,'rolling20_positive_fraction':rp,'rolling20_windows':len(rolling),'active_month_positive_fraction':float(np.mean([x['return']>0 for x in active_months])) if active_months else None,'active_rolling20_positive_fraction':float(np.mean(rolling[rex>=.25]>0)) if np.any(rex>=.25) else None,'turnover':float(turn),'cost':float(sum(x['cost'] for x in r)),'fees':float(sum(x['fee'] for x in r)),'slippage':float(sum(x['slippage'] for x in r)),'periods':len(r),'utility':float(252*logs.mean()-abs(dd)-.001*252*turn/len(r)+.1*(mp-.5)+.1*((rp or 0)-.5))}